<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, shallowRef, watch } from 'vue';
import { ElButton, ElDialog, ElTag } from 'element-plus';
import { FlaskConical, Plus, Upload, FileCheck2, ChevronRight } from 'lucide-vue-next';
import { ApiError, type PlatformApi, type Identity, type ModelEntry } from './api';
import type { EvaluationEntry } from './evaluation';
import { validPredictions, type EvaluationRun, type EvaluationRunCreate, type EvaluationPredictionImport, type RunReport, type EvaluationSummary, type Stratum } from './evaluationRuns';
import EvaluationMetrics from './EvaluationMetrics.vue';
const props = defineProps<{api: PlatformApi; identity: Identity}>();
const emit = defineEmits<{failure:[error:ApiError];revalidate:[]}>();
const readable = computed(() => props.identity.permissions.includes('platform.evaluation.read'));
const runnable = computed(() => props.identity.permissions.includes('platform.evaluation.run'));
const modelsReadable = computed(() => props.identity.permissions.includes('platform.models.read'));
const items = shallowRef<EvaluationRun[]>([]), selected = shallowRef<EvaluationRun | null>(null), report = shallowRef<RunReport | null>(null);
const offset=ref(0), next=ref<number|null>(null), loading=ref(false), detailLoading=ref(false), reporting=ref(false);
const error=ref(''), notice=ref(''), selectedId=ref(''), dialog=ref(false), kind=ref<'create'|'import'>('create');
const saving=ref(false), uncertain=ref(false), conflict=ref(false), formError=ref(''), candidatesLoading=ref(false);
const datasets=shallowRef<EvaluationEntry[]>([]), models=shallowRef<ModelEntry[]>([]), revisions=shallowRef<ModelEntry[]>([]);
const datasetOffset=ref(0), datasetNext=ref<number|null>(null), modelCursor=ref<string|undefined>(), revisionCursor=ref<string|undefined>();
const blank=()=>({dataset_id:'',model_id:'',model_revision:0,prompt_hash:'',schema_version:'grading-v1',rule_version:'math-v1',image_pipeline_version:'image-v1',strata:'[{"grade":3,"question_type":"arithmetic"}]',source_reference:'',predictions:''});
const form=reactive(blank());
type Pending = {kind:'create';body:EvaluationRunCreate} | {kind:'import';id:string;body:EvaluationPredictionImport};
let pending:Pending|null=null, alive=true, listVersion=0, detailVersion=0, reportVersion=0, formVersion=0, modelVersion=0;
const frozen=computed(()=>saving.value || uncertain.value || conflict.value);
const time=(v:string)=>new Date(v).toLocaleString('zh-CN',{hour12:false});
const strataDimension=ref<'by_grade'|'by_question_type'|'by_difficulty'|'by_grade_question_type'>('by_grade'), stratumIndex=ref(0);
const strata=computed(()=>report.value?.report[strataDimension.value] ?? []);
const activeStratum=computed(()=>strata.value[stratumIndex.value]);
const stratumTitle=(s:EvaluationSummary & Partial<Stratum> & {difficulty?:string;required?:boolean})=>[s.grade ? `${s.grade}年级`:'',s.question_type,s.difficulty ? ({easy:'简单',medium:'中等',hard:'困难'}[s.difficulty] ?? s.difficulty):'',s.required ? '必验':''].filter(Boolean).join(' / ');
watch(strataDimension,()=>{stratumIndex.value=0;});
const issueNames:Record<string,string>={critical_scope_not_defined:'未定义必要验收范围',missing_required_strata:'必要分层缺少样本',no_automatic_questions:'没有自动批改题目',no_gold_errors:'金标准缺少错题',insufficient_student_clusters:'学生簇不足',insufficient_page_clusters:'页面簇不足',undefined_student_resamples:'学生重采样存在空分母',undefined_page_resamples:'页面重采样存在空分母',required_stratum_thresholds_not_met:'必要分层未达到数值门槛'};
function clearSensitive(){listVersion++;detailVersion++;reportVersion++;formVersion++;modelVersion++;items.value=[];selected.value=null;report.value=null;selectedId.value='';datasets.value=[];models.value=[];revisions.value=[];pending=null;dialog.value=false;saving.value=false;loading.value=false;detailLoading.value=false;reporting.value=false;candidatesLoading.value=false;uncertain.value=false;conflict.value=false;next.value=null;Object.assign(form,blank());}
function handle(cause:unknown){const e=cause instanceof ApiError ? cause : new ApiError(502);if(e.code==='stale') return '';if(e.status===401||e.status===403||e.code==='invalid_session'){clearSensitive();if(e.status===403)emit('revalidate');else emit('failure',e);}return e.message;}
async function loadList(){if(!readable.value)return;const v=++listVersion;loading.value=true;error.value='';try{const value=await props.api.evaluationRuns(offset.value);if(alive&&v===listVersion){items.value=value.items;next.value=value.next_offset;}}catch(e){if(alive&&v===listVersion){items.value=[];error.value=handle(e);}}finally{if(alive&&v===listVersion)loading.value=false;}}
async function openRun(id:string){if(dialog.value||!readable.value)return;const v=++detailVersion;reportVersion++;selectedId.value=id;selected.value=null;report.value=null;detailLoading.value=true;reporting.value=false;error.value='';notice.value='';try{const value=await props.api.evaluationRun(id);if(alive&&v===detailVersion)selected.value=value;}catch(e){if(alive&&v===detailVersion)error.value=handle(e);}finally{if(alive&&v===detailVersion)detailLoading.value=false;}}
async function refresh(){if(dialog.value)return;await Promise.all([loadList(),selectedId.value?openRun(selectedId.value):Promise.resolve()]);}
function turnPage(forward:boolean){if(loading.value||dialog.value)return;offset.value=forward ? next.value??offset.value : Math.max(0,offset.value-50);void loadList();}
async function loadReport(){const run=selected.value;if(!run||!run.usable||run.state!=='completed'||dialog.value)return;const v=++reportVersion;report.value=null;reporting.value=true;error.value='';try{const value=await props.api.evaluationRunReport(run.id,run.manifest_digest);if(alive&&v===reportVersion&&selected.value?.id===run.id){report.value=value;stratumIndex.value=0;}}catch(e){if(alive&&v===reportVersion)error.value=handle(e);}finally{if(alive&&v===reportVersion)reporting.value=false;}}
function closeForm(){if(saving.value)return;formVersion++;modelVersion++;dialog.value=false;pending=null;uncertain.value=false;conflict.value=false;formError.value='';datasets.value=[];models.value=[];revisions.value=[];Object.assign(form,blank());}
async function loadCandidates(datasetPage=0, mode:'initial'|'datasets'|'models'='initial') {
  if(candidatesLoading.value)return;
  const v=formVersion;
  candidatesLoading.value=true;formError.value='';
  try {
    const [ds,ms]=await Promise.all([
      mode==='models'?Promise.resolve(null):props.api.evaluationDatasets(datasetPage),
      mode==='datasets'?Promise.resolve(null):props.api.models({cursor:mode==='models'?modelCursor.value:undefined}),
    ]);
    if(!alive||v!==formVersion)return;
    if(ds){datasets.value=ds.items;datasetOffset.value=datasetPage;datasetNext.value=ds.next_offset;if(!ds.items.some(d=>d.id===form.dataset_id))form.dataset_id='';}
    if(ms){models.value=mode==='models'?[...models.value,...ms.items]:ms.items;modelCursor.value=ms.next_cursor??undefined;}
  }catch(e){if(alive&&v===formVersion)formError.value=handle(e);}
  finally{if(alive&&v===formVersion)candidatesLoading.value=false;}
}
async function loadRevisions(more=false){if(!form.model_id)return;const v=++modelVersion,fv=formVersion,id=form.model_id;if(!more){revisions.value=[];form.model_revision=0;revisionCursor.value=undefined;}formError.value='';try{const value=await props.api.modelHistory(id,more?revisionCursor.value:undefined);if(!alive||v!==modelVersion||fv!==formVersion)return;revisions.value=more?[...revisions.value,...value.items]:value.items;revisionCursor.value=value.next_cursor??undefined;}catch(e){if(alive&&v===modelVersion&&fv===formVersion)formError.value=handle(e);}}
function openForm(value:'create'|'import'){if(!runnable.value||dialog.value)return;if(value==='create'&&!modelsReadable.value)return;if(value==='import'&&(!selected.value?.usable||selected.value.state!=='awaiting_predictions'))return;closeForm();kind.value=value;dialog.value=true;candidatesLoading.value=false;if(value==='create')void loadCandidates();}
function command():Pending{if(kind.value==='import'){const run=selected.value;if(!run)throw Error('请重新选择评测运行');const predictions:unknown=JSON.parse(form.predictions);if(!validPredictions(predictions))throw Error('预测必须为 1–50000 条唯一题目 UUID、合法判定及布尔放行标志；待复核/不支持不能自动放行。');const source=form.source_reference.trim();if(!source||source.length>200||/[\x00-\x1f\x7f]/.test(source))throw Error('请填写不超过 200 字的来源标识。');return {kind:'import',id:run.id,body:{operation_id:crypto.randomUUID(),expected_revision:run.revision,manifest_digest:run.manifest_digest,source_reference:source,predictions}};}
 const dataset=datasets.value.find(d=>d.id===form.dataset_id), model=revisions.value.find(m=>m.id===form.model_id&&m.revision===Number(form.model_revision));if(!dataset||dataset.state!=='locked'||dataset.split==='train'||!model)throw Error('请选择已锁定的验证/测试数据集及固定模型修订。');
 const required:unknown=JSON.parse(form.strata);if(!Array.isArray(required)||!required.length||required.length>100||!required.every(s=>s&&Object.keys(s).length===2&&Number.isInteger(s.grade)&&s.grade>=1&&s.grade<=6&&typeof s.question_type==='string'&&/^[a-zA-Z0-9][a-zA-Z0-9._/-]{0,119}$/.test(s.question_type))||new Set(required.map(s=>`${s.grade}:${s.question_type}`)).size!==required.length)throw Error('必要分层须为不重复的年级（1–6）与题型组合，最多 100 项。');
 if(!/^[a-f0-9]{64}$/.test(form.prompt_hash)||![form.schema_version,form.rule_version,form.image_pipeline_version].every(v=>/^[a-zA-Z0-9][a-zA-Z0-9._/-]{0,119}$/.test(v)))throw Error('提示词摘要须为 64 位小写 SHA-256；版本仅允许字母、数字、点、斜线、下划线和连字符。');
 return {kind:'create',body:{operation_id:crypto.randomUUID(),expected_revision:0,dataset_id:dataset.id,dataset_revision:dataset.revision,model_id:model.id,model_revision:model.revision,prompt_hash:form.prompt_hash,schema_version:form.schema_version,rule_version:form.rule_version,image_pipeline_version:form.image_pipeline_version,required_strata:required as Stratum[]}};
}
async function save(){if(saving.value||conflict.value||!runnable.value)return;formError.value='';try{pending??=command();}catch(e){formError.value=e instanceof SyntaxError?'JSON 格式无效，请检查括号、逗号与双引号。':(e as Error).message;return;}const request=pending,v=formVersion;saving.value=true;try{const result=request.kind==='create'?await props.api.createEvaluationRun(request.body):await props.api.importEvaluationPredictions(request.id,request.body);if(!alive||v!==formVersion)return;saving.value=false;closeForm();await Promise.all([loadList(),openRun(result.id)]);notice.value=request.kind==='create'?'评测运行已建立，模型与数据集版本已固定。':'预测已完整导入，可计算统计报告。';}catch(cause){if(!alive||v!==formVersion)return;const e=cause instanceof ApiError?cause:null;uncertain.value=!e||e.status>=500||e.status===0;conflict.value=e?.status===409;if(!uncertain.value&&!conflict.value)pending=null;formError.value=handle(cause);}finally{if(alive&&v===formVersion)saving.value=false;}}
async function readFile(event:Event){const v=formVersion,file=(event.target as HTMLInputElement).files?.[0];if(!file||frozen.value)return;if(file.size>12*1024*1024){formError.value='JSON 文件不得超过 12 MiB。';return;}try{const content=await file.text();if(alive&&v===formVersion&&!frozen.value)form.predictions=content;}catch{if(alive&&v===formVersion)formError.value='文件读取失败，请重新选择。';}}
watch(()=>props.identity.permissions.join('|'),()=>{clearSensitive();saving.value=false;loading.value=false;detailLoading.value=false;reporting.value=false;if(readable.value)void loadList();});
onMounted(loadList);onUnmounted(()=>{alive=false;clearSensitive();});defineExpose({refresh});
</script>

<template>
  <div class="run-workspace">
    <section class="surface run-intro"><div><span class="eyebrow"><FlaskConical :size="16"/> EVALUATION LAB</span><h2>让每一份评分，有据可查</h2><p>固定模型和数据集版本，导入完整预测，以服务器统计核查作业批改质量。</p></div><ElButton v-if="runnable" type="primary" :disabled="!modelsReadable || dialog" @click="openForm('create')"><Plus :size="16"/>新建评测运行</ElButton></section>
    <p class="inline-note">当前为离线预测评测。来源标识由操作人声明，不能证明真实模型调用；报告不授予生产准入。</p>
    <p v-if="runnable&&!modelsReadable" class="feedback">创建运行需要模型目录读取权限，请联系安全管理员。</p>
    <p v-if="error" class="feedback error" role="alert">{{ error }}</p><p v-if="notice" class="feedback success" role="status">{{ notice }}</p>
    <div class="run-layout"><section class="surface run-list"><div class="card-heading"><div><h2>评测运行</h2><p>第 {{ offset/50+1 }} 页 · {{ items.length }} 条</p></div><ElTag effect="plain">{{ runnable?'可执行':'只读' }}</ElTag></div>
      <p v-if="loading" role="status">正在加载运行…</p><p v-else-if="!items.length" class="empty-state">暂无评测运行。先锁定授权数据集，再建立运行。</p>
      <button v-for="item in items" :key="item.id" class="run-row" :class="{active:selectedId===item.id}" :disabled="dialog" @click="openRun(item.id)"><span><strong>{{ item.model.display_name }}</strong><small>{{ item.dataset.name }} · 模型 r{{ item.model.revision }}</small><small>{{ time(item.created_at) }}</small></span><ElTag :type="!item.usable?'danger':item.state==='completed'?'success':'info'" size="small">{{ !item.usable?'授权失效':item.state==='completed'?'已导入':'待导入' }}</ElTag><ChevronRight :size="14"/></button>
      <div class="run-pagination"><ElButton :disabled="!offset||loading||dialog" @click="turnPage(false)">上一页</ElButton><ElButton :disabled="next===null||loading||dialog" @click="turnPage(true)">下一页</ElButton></div>
    </section><div class="run-detail">
      <section v-if="detailLoading" class="surface" role="status">正在核对运行与授权…</section>
      <section v-else-if="!selected" class="surface run-placeholder"><FlaskConical :size="40"/><h2>选择一项评测运行</h2><p>核对固定清单、完整预测与统计证据。</p></section>
      <template v-else><section class="surface"><div class="card-heading"><div><span class="eyebrow muted">固定版本清单 · r{{ selected.revision }}</span><h2>{{ selected.model.display_name }}</h2></div><ElButton v-if="runnable&&selected.usable&&selected.state==='awaiting_predictions'" @click="openForm('import')"><Upload :size="16"/>导入预测</ElButton><ElButton v-if="selected.usable&&selected.state==='completed'" type="primary" :loading="reporting" @click="loadReport"><FileCheck2 :size="16"/>计算统计报告</ElButton></div>
        <p v-if="!selected.usable" class="feedback error">来源授权已失效，预测导入及报告不可用；重新授权不会复活此运行。</p>
        <dl class="details run-manifest"><div><dt>运行 ID</dt><dd class="mono">{{ selected.id }}</dd></div><div><dt>数据集</dt><dd>{{ selected.dataset.name }} · {{ selected.dataset.split }} · r{{ selected.dataset.revision }}</dd></div><div><dt>模型身份</dt><dd>{{ selected.model.provider }} / {{ selected.model.model_key }} / {{ selected.model.fixed_version }} / {{ selected.model.region }} · r{{ selected.model.revision }}</dd></div><div><dt>预测数量 / 来源</dt><dd>{{ selected.prediction_count }} / {{ selected.source_reference??'尚未导入' }}</dd></div><div><dt>完成时间</dt><dd>{{ selected.completed_at ? time(selected.completed_at) : '尚未完成' }}</dd></div><div><dt>结构 / 规则 / 图像管线</dt><dd>{{ selected.schema_version }} / {{ selected.rule_version }} / {{ selected.image_pipeline_version }}</dd></div><div><dt>必要验收分层</dt><dd>{{ selected.required_strata.map(s=>`${s.grade}年级 · ${s.question_type}`).join('；') }}</dd></div><div v-for="field in (['manifest_digest','prompt_hash'] as const)" :key="field"><dt>{{ field==='manifest_digest'?'运行清单 SHA-256':'提示词 SHA-256' }}</dt><dd class="mono">{{ selected[field] }}</dd></div><div><dt>数据集锁定 SHA-256</dt><dd class="mono">{{ selected.dataset.locked_digest }}</dd></div><div><dt>统计 / 执行方式</dt><dd>{{ selected.algorithm_version }} / {{ selected.execution_mode }}</dd></div></dl>
      </section>
      <template v-if="report"><section class="surface"><div class="card-heading"><div><span class="eyebrow muted">质量证据</span><h2>评测统计报告</h2></div><ElTag type="warning">尚未取得生产准入</ElTag></div>
        <div class="run-kpis"><div><small>评测题目</small><strong>{{ report.report.total_questions }}</strong></div><div><small>自动批改</small><strong>{{ report.report.automatic_questions }}</strong></div><div><small>自动结果冲突</small><strong>{{ report.report.conflicts }}</strong></div><div><small>数值门槛 / 样本目标</small><strong class="run-kpi-text">{{ report.report.numeric_thresholds_met?'达到':'未达到' }} / {{ report.report.sample_targets_met?'达到':'未达到' }}</strong></div></div>
        <p class="subtext">样本目标为 10,000 题、1,000 页、100 位学生；正确率和误放行率还需满足保守置信界限及必要分层要求。</p><ul v-if="report.report.evidence_issues.length" class="run-issues"><li v-for="issue in report.report.evidence_issues" :key="issue">{{ issueNames[issue]??issue }}</li></ul>
        <EvaluationMetrics :summary="report.report"/>
        <div class="run-safety"><h3>判定与安全核查</h3><p>判定分布：正确 {{ report.report.prediction_counts.correct }} · 错误 {{ report.report.prediction_counts.incorrect }} · 未作答 {{ report.report.prediction_counts.unanswered }} · 待复核 {{ report.report.prediction_counts.pending_review }} · 不支持 {{ report.report.prediction_counts.unsupported }}</p><p>未作答误判正确 {{ report.report.safety_violations.unanswered_as_correct }} · 不可判定仍放行 {{ report.report.safety_violations.unjudgeable_released }} · 应拒评仍放行 {{ report.report.safety_violations.required_abstention_released }}</p></div>
      </section><section class="surface"><div class="card-heading"><h2>分层证据</h2><select v-model="strataDimension" aria-label="分层维度"><option value="by_grade">按年级</option><option value="by_question_type">按题型</option><option value="by_difficulty">按难度</option><option value="by_grade_question_type">按年级与题型</option></select></div><label>选择分层<select v-model.number="stratumIndex"><option v-for="(s,i) in strata" :key="i" :value="i">{{ stratumTitle(s) }} · {{ s.total_questions }} 题</option></select></label><template v-if="activeStratum"><p>{{ activeStratum.total_questions }} 题 · 自动 {{ activeStratum.automatic_questions }} 题 · 冲突 {{ activeStratum.conflicts }} 题 · 数值门槛{{ activeStratum.numeric_thresholds_met?'达到':'未达到' }}</p><EvaluationMetrics :summary="activeStratum"/></template><p v-else>此维度暂无样本。</p></section>
      <section class="surface"><h2>可复核的统计方法</h2><p>算法 {{ report.report.method.algorithm_version }} · 随机种子 {{ report.report.method.seed }} · {{ report.report.method.bootstrap_resamples }} 次重采样 · {{ report.report.method.bit_generator }}</p><p class="subtext">独立样本使用分别计算的单侧 Clopper–Pearson 界限；按学生、页面整簇重采样。保守界限取三种方法的最小下界和最大上界，任一空分母重采样使对应簇界限取 0–1。</p><p class="subtext">NumPy {{ report.report.method.numpy_version }} · SciPy {{ report.report.method.scipy_version }}</p></section></template></template>
    </div></div>
    <ElDialog :model-value="dialog" :title="kind==='create'?'新建固定版本评测运行':'导入完整预测'" width="min(760px, 94vw)" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving" @update:model-value="value=>{if(!value)closeForm();}">
      <form @submit.prevent="save"><p v-if="formError" class="feedback error" role="alert">{{ formError }}</p><p v-if="uncertain" class="feedback">回执尚未确认，表单已冻结。重试会复用原操作 ID 与完整请求。</p><p v-if="conflict" class="feedback">版本、题集或授权发生冲突，请关闭后刷新核对。</p><fieldset :disabled="frozen" class="run-form">
        <template v-if="kind==='create'"><label>已锁定数据集<select v-model="form.dataset_id" required><option value="">请选择测试/验证集</option><option v-for="d in datasets" :key="d.id" :value="d.id" :disabled="d.state!=='locked'||d.split==='train'">{{ d.name }} · {{ d.split }} · r{{ d.revision }} · {{ d.state==='locked'?'已锁定':'草稿' }}</option></select></label><div class="run-pagination"><ElButton :disabled="!datasetOffset||candidatesLoading||frozen" @click="loadCandidates(Math.max(0,datasetOffset-50),'datasets')">上一页数据集</ElButton><ElButton :disabled="datasetNext===null||candidatesLoading||frozen" @click="loadCandidates(datasetNext??0,'datasets')">下一页数据集</ElButton></div><label>模型<select v-model="form.model_id" required @change="loadRevisions()"><option value="">请选择模型</option><option v-for="m in models" :key="m.id" :value="m.id">{{ m.display_name }} · {{ m.fixed_version }} / {{ m.region }}</option></select></label><ElButton v-if="modelCursor" :disabled="candidatesLoading||frozen" @click="loadCandidates(datasetOffset,'models')">加载更多模型</ElButton><label>固定历史修订<select v-model.number="form.model_revision" required><option :value="0">请选择修订</option><option v-for="m in revisions" :key="m.revision" :value="m.revision">r{{ m.revision }} · {{ m.display_name }} · {{ m.reason }}</option></select></label><ElButton v-if="revisionCursor" :disabled="frozen" @click="loadRevisions(true)">加载更多修订</ElButton>
          <label>提示词 SHA-256<input v-model="form.prompt_hash" required maxlength="64" placeholder="64 位小写十六进制摘要"/></label><div class="run-version-fields"><label>结构版本<input v-model="form.schema_version" required maxlength="120"/></label><label>规则版本<input v-model="form.rule_version" required maxlength="120"/></label><label>图像管线版本<input v-model="form.image_pipeline_version" required maxlength="120"/></label></div><label>必要验收分层（JSON）<textarea v-model="form.strata" required rows="4" spellcheck="false"/></label><p class="subtext">例：[{"grade":3,"question_type":"arithmetic"}]。创建后清单不可修改。</p>
        </template><template v-else><p>将导入与清单摘要 {{ selected?.manifest_digest }} 绑定。必须精确覆盖该数据集全部样本 UUID；服务器计算指标，拒绝客户端准确率。</p><label>离线预测来源标识<input v-model="form.source_reference" required maxlength="200" placeholder="例如 offline-run-20261026-01"/></label><label>选择 JSON 文件（最多 12 MiB）<input type="file" accept="application/json,.json" @change="readFile"/></label><label>完整预测 JSON 数组<textarea v-model="form.predictions" required rows="10" spellcheck="false"/></label><p class="subtext">格式：[{"question_id":"样本 UUID","verdict":"incorrect","automatic_release":true}]。判定支持 correct / incorrect / unanswered / pending_review / unsupported。导入完成后不可覆盖。</p></template>
      </fieldset><div class="run-form-actions"><ElButton :disabled="saving" @click="closeForm">关闭</ElButton><ElButton native-type="submit" type="primary" :loading="saving" :disabled="conflict||candidatesLoading">{{ uncertain?'原样重试':kind==='create'?'建立评测运行':'确认完整导入' }}</ElButton></div></form>
    </ElDialog>
  </div>
</template>
